alter table public.powerlifting_athletes add column if not exists arenapl_url text;
drop function if exists public.get_powerlifting_rankings();
create function public.get_powerlifting_rankings() returns table(id uuid,athlete_id uuid,client_id uuid,athlete_name text,sex text,bodyweight_kg numeric,squat_kg numeric,bench_kg numeric,deadlift_kg numeric,total_kg numeric,points numeric,points_system text,meet_name text,meet_location text,meet_date date,competition_level text,weight_class_kg text,federation text,arenapl_url text) language sql stable security definer set search_path=public as $$ select r.id,r.athlete_id,r.client_id,r.athlete_name,r.sex,r.bodyweight_kg,r.squat_kg,r.bench_kg,r.deadlift_kg,r.total_kg,r.points,r.points_system,r.meet_name,r.meet_location,r.meet_date,r.competition_level,r.weight_class_kg,r.federation,a.arenapl_url from public.athlete_powerlifting_results r join public.powerlifting_athletes a on a.id=r.athlete_id where auth.uid() is not null and exists(select 1 from public.powerlifting_coaching_periods p where p.athlete_id=r.athlete_id and (p.start_date is null or r.meet_date>=p.start_date) and (p.end_date is null or r.meet_date<=p.end_date)) order by r.points desc nulls last,r.total_kg desc; $$;
grant execute on function public.get_powerlifting_rankings() to authenticated;